	__models__GongNoteShape__00000002_.IsExpanded = false
	__models__GongNoteShape__00000003_.Name = `04. AuthorityForAirspace & GeoBorder-Note04GeoBorder`
	__models__GongNoteShape__00000003_.Identifier = `ref_models.Note04GeoBorder`
	__models__GongNoteShape__00000003_.Body = `04. AuthorityForAirspace & GeoBorder Story

[models.AuthorityForAirspaceTimeSliceType] assigns responsible organizations (civil/military jurisdiction) to an airspace.
[models.GeoBorderTimeSliceType] models political coastlines or state borders using 2D [models.CurveType] and 3D [models.ElevatedCurveType] geometries.
`
	__models__GongNoteShape__00000003_.BodyHTML = `<p>04. AuthorityForAirspace &amp; GeoBorder Story
<p><a href="/models#AuthorityForAirspaceTimeSliceType">models.AuthorityForAirspaceTimeSliceType</a> assigns responsible organizations (civil/military jurisdiction) to an airspace.
<a href="/models#GeoBorderTimeSliceType">models.GeoBorderTimeSliceType</a> models political coastlines or state borders using 2D <a href="/models#CurveType">models.CurveType</a> and 3D <a href="/models#ElevatedCurveType">models.ElevatedCurveType</a> geometries.
`
	__models__GongNoteShape__00000003_.X = 40.000000
