	__models__GongNoteShape__00000004_.Name = `05. Airspace GML 3.2.1 Surface & Curve Segments-Note05GMLGeometry`
	__models__GongNoteShape__00000004_.Identifier = `ref_models.Note05GMLGeometry`
	__models__GongNoteShape__00000004_.Body = `05. Airspace GML 3.2.1 Surface & Curve Segments Story

AIXM [models.SurfaceType] and [models.CurveType] extend ISO 19107 / GML 3.2.1 geometry primitives.
A surface is composed of [models.PolygonPatchType] bounded by a [models.LinearRingType], whose segments are built from
[models.GeodesicStringType], [models.ArcByCenterPointType], or [models.CircleByCenterPointType] coordinate lists ([models.DirectPositionListType]).
`
	__models__GongNoteShape__00000004_.BodyHTML = `<p>05. Airspace GML 3.2.1 Surface &amp; Curve Segments Story
<p>AIXM <a href="/models#SurfaceType">models.SurfaceType</a> and <a href="/models#CurveType">models.CurveType</a> extend ISO 19107 / GML 3.2.1 geometry primitives.
A surface is composed of <a href="/models#PolygonPatchType">models.PolygonPatchType</a> bounded by a <a href="/models#LinearRingType">models.LinearRingType</a>, whose segments are built from
<a href="/models#GeodesicStringType">models.GeodesicStringType</a>, <a href="/models#ArcByCenterPointType">models.ArcByCenterPointType</a>, or <a href="/models#CircleByCenterPointType">models.CircleByCenterPointType</a> coordinate lists (<a href="/models#DirectPositionListType">models.DirectPositionListType</a>).
`
